package com.funfriday.db.dao;
import com.funfriday.db.DatabaseConnectionProvider;import com.funfriday.db.model.LogicGridPuzzleProgress;import java.sql.*;import java.util.*;
public class PlayerLogicGridProgressDao {private final DatabaseConnectionProvider cp;public PlayerLogicGridProgressDao(DatabaseConnectionProvider cp){this.cp=cp;}public Map<Long,LogicGridPuzzleProgress> find(String player,List<Long> ids)throws SQLException{if(player==null||player.isBlank()||ids.isEmpty())return Map.of();String q="SELECT puzzle_id,best_progress_percent,is_completed FROM player_logic_grid_progress WHERE player_id=? AND puzzle_id IN ("+String.join(",",Collections.nCopies(ids.size(),"?"))+")";Map<Long,LogicGridPuzzleProgress>out=new HashMap<>();try(Connection c=cp.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setString(1,player);for(int i=0;i<ids.size();i++)s.setLong(i+2,ids.get(i));try(ResultSet r=s.executeQuery()){while(r.next())out.put(r.getLong(1),new LogicGridPuzzleProgress(r.getInt(2),r.getBoolean(3)));}}return out;}public void save(String player,long puzzle,int progress,boolean complete)throws SQLException{if(player==null||player.isBlank()||puzzle<=0)return;try(Connection c=cp.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO player_logic_grid_progress(player_id,puzzle_id,best_progress_percent,is_completed,completed_at) VALUES(?,?,?,?,CASE WHEN ? THEN CURRENT_TIMESTAMP ELSE NULL END) ON DUPLICATE KEY UPDATE best_progress_percent=GREATEST(best_progress_percent,VALUES(best_progress_percent)),is_completed=is_completed OR VALUES(is_completed),last_played_at=CURRENT_TIMESTAMP,completed_at=CASE WHEN completed_at IS NULL AND VALUES(is_completed) THEN CURRENT_TIMESTAMP ELSE completed_at END")){s.setString(1,player);s.setLong(2,puzzle);s.setInt(3,Math.max(0,Math.min(100,progress)));s.setBoolean(4,complete);s.setBoolean(5,complete);s.executeUpdate();}}}
